Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
sctp: change to check peer prsctp_capable when using prsctp
 polices

Now before using prsctp polices, sctp uses asoc->prsctp_enable to
check if prsctp is enabled. However asoc->prsctp_enable is set only
means local host support prsctp, sctp should not abandon packet if
peer host doesn't enable prsctp.

So this patch is to use asoc->peer.prsctp_capable to check if prsctp
is enabled on both side, instead of asoc->prsctp_enable, as asoc's
peer.prsctp_capable is set only when local and peer both enable prsctp.

Fixes: a6c2f792873a ("sctp: implement prsctp TTL policy")
Signed-off-by: Xin Long <lucien.xin@gmail.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The bug was caused by the incorrect assumption that the presence of `asoc->prsctp_enable` (indicating local support for PR-SCTP) was sufficient to determine whether PR-SCTP policies should be applied. This led to situations where packets could be abandoned or mishandled if the peer did not also support PR-SCTP, as the local host was not checking the peer's capability (`asoc->peer.prsctp_capable`), which is essential for proper PR-SCTP functionality.

Here is the patch:
  */
 struct sctp_datamsg *sctp_datamsg_from_user(struct sctp_association *asoc,
 					    struct sctp_sndrcvinfo *sinfo,
 					    struct iov_iter *from)
 {
 	int max, whole, i, offset, over, err;
 	int len, first_len;
 	int max_data;
 	struct sctp_chunk *chunk;
 	struct sctp_datamsg *msg;
 	struct list_head *pos, *temp;
 	size_t msg_len = iov_iter_count(from);
 	__u8 frag;

 	msg = sctp_datamsg_new(GFP_KERNEL);
 	if (!msg)
 		return ERR_PTR(-ENOMEM);

 	/* Note: Calculate this outside of the loop, so that all fragments
 	 * have the same expiration.
 	 */
 	if (sinfo->sinfo_timetolive) {
 		/* sinfo_timetolive is in milliseconds */
 		msg->expires_at = jiffies +
 				    msecs_to_jiffies(sinfo->sinfo_timetolive);
 		msg->can_abandon = 1;

 		pr_debug("%s: msg:%p expires_at:%ld jiffies:%ld\n", __func__,
 			 msg, msg->expires_at, jiffies);
 	}

-	if (asoc->prsctp_enable &&
+	if (asoc->peer.prsctp_capable &&
 	    SCTP_PR_TTL_ENABLED(sinfo->sinfo_flags))
 		msg->expires_at =
 			jiffies + msecs_to_jiffies(sinfo->sinfo_timetolive);

 	/* This is the biggest possible DATA chunk that can fit into
 	 * the packet
 	 */
 	max_data = (asoc->pathmtu -
 		sctp_sk(asoc->base.sk)->pf->af->net_header_len -
 		sizeof(struct sctphdr) - sizeof(struct sctp_data_chunk)) & ~3;

 	max = asoc->frag_point;
 	/* If the the peer requested that we authenticate DATA chunks
 	 * we need to account for bundling of the AUTH chunks along with
 	 * DATA.
 	 */
 	if (sctp_auth_send_cid(SCTP_CID_DATA, asoc)) {
 		struct sctp_hmac *hmac_desc = sctp_auth_asoc_get_hmac(asoc);

 		if (hmac_desc)
 			max_data -= WORD_ROUND(sizeof(sctp_auth_chunk_t) +
 					    hmac_desc->hmac_len);
 	}

 	/* Now, check if we need to reduce our max */
 	if (max > max_data)
 		max = max_data;

 	whole = 0;
 	first_len = max;

 	/* Check to see if we have a pending SACK and try to let it be bundled
 	 * with this message.  Do this if we don't have any data queued already.
 	 * To check that, look at out_qlen and retransmit list.
 	 * NOTE: we will not reduce to account for SACK, if the message would
 	 * not have been fragmented.
 	 */
 	if (timer_pending(&asoc->timers[SCTP_EVENT_TIMEOUT_SACK]) &&
 	    asoc->outqueue.out_qlen == 0 &&
 	    list_empty(&asoc->outqueue.retransmit) &&
 	    msg_len > max)
 		max_data -= WORD_ROUND(sizeof(sctp_sack_chunk_t));

 	/* Encourage Cookie-ECHO bundling. */
 	if (asoc->state < SCTP_STATE_COOKIE_ECHOED)
 		max_data -= SCTP_ARBITRARY_COOKIE_ECHO_LEN;

 	/* Now that we adjusted completely, reset first_len */
 	if (first_len > max_data)
 		first_len = max_data;

 	/* Account for a different sized first fragment */
 	if (msg_len >= first_len) {
 		msg_len -= first_len;
 		whole = 1;
 		msg->can_delay = 0;
 	}

 	/* How many full sized?  How many bytes leftover? */
 	whole += msg_len / max;
 	over = msg_len % max;
 	offset = 0;

 	if ((whole > 1) || (whole && over))
 		SCTP_INC_STATS(sock_net(asoc->base.sk), SCTP_MIB_FRAGUSRMSGS);

 	/* Create chunks for all the full sized DATA chunks. */
 	for (i = 0, len = first_len; i < whole; i++) {
 		frag = SCTP_DATA_MIDDLE_FRAG;

 		if (0 == i)
 			frag |= SCTP_DATA_FIRST_FRAG;

 		if ((i == (whole - 1)) && !over) {
 			frag |= SCTP_DATA_LAST_FRAG;

 			/* The application requests to set the I-bit of the
 			 * last DATA chunk of a user message when providing
 			 * the user message to the SCTP implementation.
 			 */
 			if ((sinfo->sinfo_flags & SCTP_EOF) ||
 			    (sinfo->sinfo_flags & SCTP_SACK_IMMEDIATELY))
 				frag |= SCTP_DATA_SACK_IMM;
 		}

 		chunk = sctp_make_datafrag_empty(asoc, sinfo, len, frag,
 						 0, GFP_KERNEL);

 		if (!chunk) {
 			err = -ENOMEM;
 			goto errout;
 		}

 		err = sctp_user_addto_chunk(chunk, len, from);
 		if (err < 0)
 			goto errout_chunk_free;

 		/* Put the chunk->skb back into the form expected by send.  */
 		__skb_pull(chunk->skb, (__u8 *)chunk->chunk_hdr
 			   - (__u8 *)chunk->skb->data);

 		sctp_datamsg_assign(msg, chunk);
 		list_add_tail(&chunk->frag_list, &msg->chunks);

 		/* The first chunk, the first chunk was likely short
 		 * to allow bundling, so reset to full size.
 		 */
 		if (0 == i)
 			len = max;
 	}

 	/* .. now the leftover bytes. */
 	if (over) {
 		if (!whole)
 			frag = SCTP_DATA_NOT_FRAG;
 		else
 			frag = SCTP_DATA_LAST_FRAG;

 		if ((sinfo->sinfo_flags & SCTP_EOF) ||
 		    (sinfo->sinfo_flags & SCTP_SACK_IMMEDIATELY))
 			frag |= SCTP_DATA_SACK_IMM;

 		chunk = sctp_make_datafrag_empty(asoc, sinfo, over, frag,
 						 0, GFP_KERNEL);

 		if (!chunk) {
 			err = -ENOMEM;
 			goto errout;
 		}

 		err = sctp_user_addto_chunk(chunk, over, from);

 		/* Put the chunk->skb back into the form expected by send.  */
 		__skb_pull(chunk->skb, (__u8 *)chunk->chunk_hdr
 			   - (__u8 *)chunk->skb->data);
 		if (err < 0)
 			goto errout_chunk_free;

 		sctp_datamsg_assign(msg, chunk);
 		list_add_tail(&chunk->frag_list, &msg->chunks);
 	}

 	return msg;

 errout_chunk_free:
 	sctp_chunk_free(chunk);

 errout:
 	list_for_each_safe(pos, temp, &msg->chunks) {
 		list_del_init(pos);
 		chunk = list_entry(pos, struct sctp_chunk, frag_list);
 		sctp_chunk_free(chunk);
 	}
 	sctp_datamsg_put(msg);
 	return ERR_PTR(err);
 }

 /* Check whether this message has expired. */
 int sctp_chunk_abandoned(struct sctp_chunk *chunk)
 {
-	if (!chunk->asoc->prsctp_enable ||
+	if (!chunk->asoc->peer.prsctp_capable ||
 	    !SCTP_PR_POLICY(chunk->sinfo.sinfo_flags)) {
 		struct sctp_datamsg *msg = chunk->msg;

 		if (!msg->can_abandon)
 			return 0;

 		if (time_after(jiffies, msg->expires_at))
 			return 1;

 		return 0;
 	}

 	if (SCTP_PR_TTL_ENABLED(chunk->sinfo.sinfo_flags) &&
 	    time_after(jiffies, chunk->msg->expires_at)) {
 		if (chunk->sent_count)
 			chunk->asoc->abandoned_sent[SCTP_PR_INDEX(TTL)]++;
 		else
 			chunk->asoc->abandoned_unsent[SCTP_PR_INDEX(TTL)]++;
 		return 1;
 	} else if (SCTP_PR_RTX_ENABLED(chunk->sinfo.sinfo_flags) &&
 		   chunk->sent_count > chunk->sinfo.sinfo_timetolive) {
 		chunk->asoc->abandoned_sent[SCTP_PR_INDEX(RTX)]++;
 		return 1;
 	}
 	/* PRIO policy is processed by sendmsg, not here */

 	return 0;
 }



